bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
root=/home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot
test "$(systemctl --user is-active gace-userbot-verify.service)" = active || exit 60
test -S "$root/deploy/secrets/userbot_verify.sock" || exit 61
spec="$(docker exec -w /opt/videobot "$cid" node --input-type=module -e '
import pg from "pg";import {readFileSync} from "node:fs";
const e=process.env,pw=readFileSync("/run/secrets/videobot_db_password","utf8").trim();
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:pw,max:1,connectionTimeoutMillis:5000});
try{
const q=await db.query("SELECT a.free_message_ids AS old_free,a.paid_message_id AS old_paid,a.topic_id AS old_topic,b.free_message_ids AS new_free,b.paid_message_id AS new_paid,b.topic_id AS new_topic,l.price_stars FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id JOIN videobot_post_receipts b ON b.listing_id=a.listing_id AND b.revision=l.revision WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[] AND a.status='sent' AND b.status='sent' AND b.paid_message_id<>a.paid_message_id");
if(q.rowCount!==1)process.exitCode=70;
else{
 const r=q.rows[0];
 const prev=[...r.old_free,r.old_paid].map(Number),next=[...r.new_free,r.new_paid].map(Number);
 if(prev.length!==3||next.length!==3||new Set([...prev,...next]).size!==6)process.exitCode=71;
 else console.log(JSON.stringify({old:{ids:prev,thread:Number(r.old_topic)},newer:{ids:next,thread:Number(r.new_topic)}}));
}
}catch{process.exitCode=79}finally{await db.end()}
')" || exit 62
GACE_SPEC="$spec" "$root/deploy/.userbot-venv/bin/python" -B - <<'PY'
import asyncio,json,os,pathlib,uuid,sys
data=json.loads(os.environ["GACE_SPEC"])
sock=pathlib.Path("/home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot/deploy/secrets/userbot_verify.sock")
async def call(spec):
 reader,writer=await asyncio.wait_for(asyncio.open_unix_connection(str(sock)),5)
 try:
  k=uuid.uuid4().hex
  q={"request_id":k,"action":"video_sale_payment_form","chat_id":-1002373696859,
     "thread_id":spec["thread"],"message_ids":spec["ids"]}
  writer.write((json.dumps(q)+"\n").encode());await writer.drain()
  response=await asyncio.wait_for(reader.readline(),40)
  if not response:sys.exit(71)
  result=json.loads(response)
  if result.get("status")!="PASS":sys.exit(72)
  if result.get("request_id")!=k:sys.exit(73)
  return result
 finally:
  writer.close();await writer.wait_closed()
try:
 old=asyncio.run(call(data["old"]))
 new=asyncio.run(call(data["newer"]))
 if old.get("stars_purchase_form") is not True or new.get("stars_purchase_form") is not True:sys.exit(74)
 if old.get("currency_xtr") is not True or new.get("currency_xtr") is not True:sys.exit(75)
 if old.get("quote_matches_media") is not True or new.get("quote_matches_media") is not True:sys.exit(76)
 if old.get("not_purchased") is not True or new.get("not_purchased") is not True:sys.exit(77)
 print("TELEGRAM_OLD_NEW_PAID_MEDIA_UNPURCHASED_FORM=PASS")
 print("TELEGRAM_NEW_PAID_VIDEO_PRICE_XTR=PASS")
except TimeoutError:sys.exit(78)
except ConnectionError:sys.exit(79)
PY
